python3 -c "
import json
with open('/app/resources/treasury_bulletin_1970_06.json', 'r') as f:
    data = json.load(f)

# Print keys at top level
def find_keys(obj, target, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if target.lower() in k.lower():
                print(f'Found at: {path}.{k}')
            find_keys(v, target, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_keys(item, target, f'{path}[{i}]')

find_keys(data, 'railroad')
"
